import { registerWebComponents } from '@domg-wc/common';
import { VlFunctionalHeaderComponent, VlTabsComponent } from '@domg-wc/components/block';

// VlTabsComponent registreert zelf vl-tabs-pane. Met within-functional-header toont vl-tabs enkel de tabs, niet de
// inhoud van de panes; met disable-links krijgen de tabs geen href, zodat een klik de url niet aanpast.
registerWebComponents([VlFunctionalHeaderComponent, VlTabsComponent]);

// change volgt bij een klik op een tab die nog niet actief is, met het id van die tab in detail.activeTab. Het event
// bubbelt niet: luister op vl-tabs zelf, niet op de functional header.
document.querySelector('vl-tabs').addEventListener('change', (event) => {
    console.log(event.detail.activeTab);
});
